{"command":"cd /tmp/wtest
cat > go.mod <<'EOF'
module example.com/wtest
go 1.21
require example.com/ext  v0.0.0
replace example.com/ext => ./ext
EOF
rm -f .wrapcheck.yaml
cat > ext/ext.go <<'EOF'
package ext
import "errors"
func Do() error { return errors.New("oops") }
func Do2() (int, error) { return 0, errors.New("oops") }
EOF

cat > pkg1/pkg1.go <<'EOF'
package pkg1
import "example.com/ext"
func MyWrap(e error, m string) error { return e }
func Foo() error {
    err := ext.Do()
    if err != nil {
        return err
    }
    return nil
}
func Bar() error {
    err := ext.Do()
    if err != nil {
        return MyWrap(err, "msg")
    }
    return nil
}
func Baz() error {
    return ext.Do()
}
func Qux() error {
    return MyWrap(ext.Do(), "msg")
}
EOF
/workspace/executable ./... 2>&1
/workspace/executable -json ./... 2>&1

# Now test with a function that returns error from same package but does not wrap
cat > pkg1/pkg1.go <<'EOF'
package pkg1
import "example.com/ext"
func Internal() error { return ext.Do() }
func Foo() error {
    err := Internal()
    if err != nil {
        return err
    }
    return nil
}
EOF
