cat <<'YAML' > .wrapcheck.yaml
reportInternalErrors: true
YAML
/workspace/executable ./... 2>&1
cat <<'YAML' > .wrapcheck.yaml
reportInternalErrors: false
YAML
/workspace/executable ./... 2>&1
rm .wrapcheck.yaml

# Test returning value that is not error from external directly, but returned as is?
cat > pkg1/pkg1.go <<'EOF'
package pkg1
import "example.com/ext"
func Foo() error {
    _, err := ext.Do2()
    if err != nil {
        return err
    }
    return nil
}
EOF
/workspace/executable ./... 2>&1

# Test ignoring sig regex
cat > pkg1/pkg1.go <<'EOF'
package pkg1
