    err := ext.Do()
    if err != nil {
        return err
    }
    return nil
}
EOF
cat <<'YAML' > .wrapcheck.yaml
ignoreSigRegexps:
- Do\(\)
YAML
/workspace/executable ./... 2>&1
rm .wrapcheck.yaml

# Test ignorePackageGlobs
cat <<'YAML' > .wrapcheck.yaml
ignorePackageGlobs:
- example.com/ext
YAML
/workspace/executable ./... 2>&1
rm .wrapcheck.yaml

# Test extraIgnoreSigs
cat > pkg1/pkg1.go <<'EOF'
package pkg1
import "example.com/ext"
func MyCustomError(e error) error { return e }
func Foo() error {
    err := ext.Do()
    if err != nil {
        return err
    }
    return nil
}
func Bar() error {
    err := ext.Do()
    if err != nil {
        return MyCustomError(err)
    }
    return nil
}
EOF
/workspace/executable ./... 2>&1
cat <<'YAML' > .wrapcheck.yaml
extraIgnoreSigs:
- MyCustomError
YAML
/workspace/executable ./... 2>&1
# Does extraIgnore affect wrapping or origin?
# Try ignoreSigs for origin
cat <<'YAML' > .wrapcheck.yaml
ignoreSigs:
- Do()
YAML
/workspace/executable ./... 2>&1
rm .wrapcheck.yaml

# Test ignoreInterfaceRegexps
cat > ext/ext.go <<'EOF'
package ext
import "errors"
type MyCache interface { Get() error }
type MyCacheImpl struct{}
func (m MyCacheImpl) Get() error { return errors.New("oops") }
func Do() error { return errors.New("oops") }
func DoCache(c MyCache) error { return c.Get() }
EOF

cat > pkg1/pkg1.go <<'EOF'
package pkg1
import "example.com/ext"
func Foo(c ext.MyCache) error {
    err := ext.DoCache(c)
    if err != nil {
        return err
    }
    return nil
}
func Bar(c ext.MyCache) error {
    err := c.Get()
    if err != nil {
        return err
    }
    return nil
}
EOF
/workspace/executable ./... 2>&1
cat <<'YAML' > .wrapcheck.yaml
ignoreInterfaceRegexps:
- Cache
YAML
/workspace/executable ./... 2>&1
