    err := ext.Do()
    if err != nil {
        return err
    }
    return nil
}
EOF
/workspace/executable -c 1 ./... 2>&1
/workspace/executable -c 0 ./... 2>&1
/workspace/executable -c 2 ./... 2>&1
/workspace/executable -c -1 ./... 2>&1

# Test test files flag
cat > pkg1/pkg1_test.go <<'EOF'
package pkg1
import "example.com/ext"
import "testing"
func TestFoo(t *testing.T) {
    err := ext.Do()
    if err != nil {
        _ = err
    }
}
func TestBar(t *testing.T) error {
    err := ext.Do()
    if err != nil {
        return err
    }
    return nil
}
EOF
/workspace/executable ./... 2>&1
/workspace/executable -test=false ./... 2>&1
rm pkg1/pkg1_test.go
"}

