type Config struct {
IgnoreSigs []string
ExtraIgnoreSigs []string
IgnoreSigRegexps []string
IgnorePackageGlobs []string
IgnoreInterfaceRegexps []string
ReportInternalErrors bool
compiledSigRegexps []*regexp.Regexp
compiledInterfaceRegexps []*regexp.Regexp
}

func defaultConfig() Config {
c := Config{
 IgnoreSigs: []string{
  ".Errorf(",
  "errors.New(",
  "errors.Unwrap(",
  "errors.Join(",
  ".Wrap(",
  ".Wrapf(",
  ".WithMessage(",
  ".WithMessagef(",
  ".WithStack(",
 },
}
c.compile()
return c
}

func (c *Config) compile() {
for _, r := range c.IgnoreSigRegexps {
 if re, err := regexp.Compile(r); err == nil {
  c.compiledSigRegexps = append(c.compiledSigRegexps, re)
 }
}
for _, r := range c.IgnoreInterfaceRegexps {
 if re, err := regexp.Compile(r); err == nil {
  c.compiledInterfaceRegexps = append(c.compiledInterfaceRegexps, re)
 }
}
}

type originInfo struct {
sig string
pkgPath string
isInterface bool
interfaceName string
isIgnored bool
}

func isErrorType(t types.Type) bool {
if t == nil { return false }
if named, ok := t.(*types.Named); ok {
 if obj := named.Obj(); obj != nil && obj.Pkg() == nil && obj.Name() == "error" {
  return true
 }
 // also check if underlying is interface with method Error() string
 // but simpler: check if type string is "error"
 if t.String() == "error" {
  return true
 }
}
return t.String() == "error"
}

func getCallOrigin(call *ast.CallExpr, info *types.Info, cfg *Config) *originInfo {
var obj types.Object
switch fun := call.Fun.(type) {
case *ast.Ident:
 obj = info.ObjectOf(fun)
case *ast.SelectorExpr:
 obj = info.ObjectOf(fun.Sel)
}
if obj == nil {
 return nil
}
sigStr := obj.String()
pkgPath := ""
if obj.Pkg() != nil {
 pkgPath = obj.Pkg().Path()
}
isIgnored := false
for _, ign := range cfg.IgnoreSigs {
 if strings.Contains(sigStr, ign) {
  isIgnored = true
  break
 }
}
if !isIgnored {
 for _, ign := range cfg.ExtraIgnoreSigs {
  if strings.Contains(sigStr, ign) {
   isIgnored = true
   break
  }
 }
}
if !isIgnored {
 for _, re := range cfg.compiledSigRegexps {
  if re.MatchString(sigStr) {
   isIgnored = true
   break
  }
 }
}
isInterface := false
interfaceName := ""
// Detect if call is interface method: check receiver type
if sel, ok := call.Fun.(*ast.SelectorExpr); ok {
 if tv, ok := info.Types[sel.X]; ok {
  t := tv.Type
  // deref pointer?
  if ptr, ok := t.(*types.Pointer); ok {
   t = ptr.Elem()
  }
  if iface, ok := t.Underlying().(*types.Interface); ok {
   isInterface = true
   // get interface name from type
   // If named type, get name
   if named, ok := tv.Type.(*types.Named); ok {
    interfaceName = named.Obj().Name()
   } else {
    interfaceName = t.String()
   }
   _ = iface
  } else if named, ok := t.(*types.Named); ok {
   // check if named type is interface
   if _, ok := named.Underlying().(*types.Interface); ok {
    isInterface = true
    interfaceName = named.Obj().Name()
   }
  }
 }
}
return &originInfo{
 sig: sigStr,
 pkgPath: pkgPath,
 isInterface: isInterface,
 interfaceName: interfaceName,
 isIgnored: isIgnored,
}
}

func main() {
cfg := defaultConfig()
l := newLoader()
visited := make(map[string]bool)
pkg, info, files, err := l.loadRecursive("/tmp/wtest", "example.com/wtest/pkg1", visited)
if err != nil { panic(err) }
fmt.Println("loaded", pkg.Path())

// For each file, find func decls
for _, f := range files {
 for _, decl := range f.Decls {
  fn, ok := decl.(*ast.FuncDecl)
  if !ok { continue }
  if fn.Body == nil { continue }
  fmt.Printf("\nFunction %s\n", fn.Name.Name)
  env := make(map[types.Object]*originInfo)
  // process body
  processBlock(fn.Body, info, cfg, env, pkg.Path())
 }
}
}

func processBlock(block *ast.BlockStmt, info *types.Info, cfg *Config, env map[types.Object]*originInfo, curPkg string) {
for _, stmt := range block.List {
 processStmt(stmt, info, cfg, env, curPkg)
}
}

func processStmt(stmt ast.Stmt, info *types.Info, cfg *Config, env map[types.Object]*originInfo, curPkg string) {
switch s := stmt.(type) {
case *ast.AssignStmt:
 // handle RHS
 // For each LHS
 for i, lhs := range s.Lhs {
  ident, ok := lhs.(*ast.Ident)
  if !ok { continue }
  obj := info.ObjectOf(ident)
  if obj == nil { continue }
  var origin *originInfo
  // RHS could be call, ident, etc.
  if len(s.Rhs) == 1 {
   // single RHS may return multiple values?
   rhs := s.Rhs[0]
   if call, ok := rhs.(*ast.CallExpr); ok {
    // check if call returns tuple and LHS has multiple
    // For simplicity, if LHS len >1, we need to find which return value is error
    // We'll get type of call and see.
    origin = getCallOrigin(call, info, cfg)
    // If this assign has multiple LHS and single RHS that is multi-return, origin applies to each error var?
    // We'll assign if this LHS is error type
    if tv, ok := info.Types[ident]; ok {
     // not used
     _ = tv
    }
   } else if id, ok := rhs.(*ast.Ident); ok {
    // assigning from another var
    if srcObj := info.ObjectOf(id); srcObj != nil {
     if srcOrigin, ok := env[srcObj]; ok {
      origin = srcOrigin
     }
    }
   }
  } else {
   // multiple RHS, match by index
   if i < len(s.Rhs) {
    rhs := s.Rhs[i]
    if call, ok := rhs.(*ast.CallExpr); ok {
     origin = getCallOrigin(call, info, cfg)
    } else if id, ok := rhs.(*ast.Ident); ok {
     if srcObj := info.ObjectOf(id); srcObj != nil {
      if srcOrigin, ok := env[srcObj]; ok {
       origin = srcOrigin
      }
     }
    }
   }
  }
  if origin != nil {
   env[obj] = origin
   fmt.Printf("  assign %s = origin %s ignored=%v pkg=%s iface=%v\n", ident.Name, origin.sig, origin.isIgnored, origin.pkgPath, origin.isInterface)
  } else {
   // if RHS is not call, maybe clear?
   // For now if RHS is error creation that is ignored, we already have isIgnored true
   // If RHS is identifier that has ignored origin, then env will have ignored.
   // If RHS is something else, we might want to clear env or set to nil?
  }
 }
case *ast.DeclStmt:
 // var decl
 if gen, ok := s.Decl.(*ast.GenDecl); ok {
  for _, spec := range gen.Specs {
   if vs, ok := spec.(*ast.ValueSpec); ok {
    for i, name := range vs.Names {
     obj := info.ObjectOf(name)
     if obj == nil { continue }
     var origin *originInfo
     if i < len(vs.Values) {
      rhs := vs.Values[i]
      if call, ok := rhs.(*ast.CallExpr); ok {
       origin = getCallOrigin(call, info, cfg)
      } else if id, ok := rhs.(*ast.Ident); ok {
       if srcObj := info.ObjectOf(id); srcObj != nil {
        if srcOrigin, ok := env[srcObj]; ok {
         origin = srcOrigin
        }
       }
      }
     } else if len(vs.Values) == 1 {
      rhs := vs.Values[0]
      if call, ok := rhs.(*ast.CallExpr); ok {
       // need to handle multi return
       origin = getCallOrigin(call, info, cfg)
      }
     }
     if origin != nil {
      env[obj] = origin
      fmt.Printf("  var %s = origin %s\n", name.Name, origin.sig)
     }
    }
   }
  }
 }
case *ast.ReturnStmt:
 for _, expr := range s.Results {
  // check if error type
  if tv, ok := info.Types[expr]; ok {
   if !isErrorType(tv.Type) {
    continue
   }
  }
  var origin *originInfo
  switch e := expr.(type) {
  case *ast.Ident:
   if obj := info.ObjectOf(e); obj != nil {
    if o, ok := env[obj]; ok {
     origin = o
    } else {
     // maybe param or global? no origin
     fmt.Printf("  return ident %s with no origin\n", e.Name)
    }
   }
  case *ast.CallExpr:
   origin = getCallOrigin(e, info, cfg)
   fmt.Printf("  return call origin %s ignored=%v pkg=%s iface=%v\n", origin.sig, origin.isIgnored, origin.pkgPath, origin.isInterface)
  default:
   fmt.Printf("  return other expr %T\n", e)
  }
  if origin != nil && !origin.isIgnored {
   // check ignore package globs
   ignorePkg := false
   for _, glob := range cfg.IgnorePackageGlobs {
    matched, _ := path.Match(glob, origin.pkgPath)
    // also try filepath.Match
    if matched {
     ignorePkg = true
     break
    }
    // support **? use simple prefix check?
    if strings.Contains(glob, "*") {
     // convert glob to regex simple
     // For now, also check if glob without * matches prefix?
    }
   }
   if ignorePkg { continue }
   // check interface regex
   if origin.isInterface {
    for _, re := range cfg.compiledInterfaceRegexps {
     if re.MatchString(origin.interfaceName) {
      ignorePkg = true
      break
     }
    }
    if ignorePkg { continue }
   }
   // determine message
   if origin.isInterface {
    fmt.Printf("  -> REPORT interface method should be wrapped: %s\n", origin.sig)
   } else if origin.pkgPath != curPkg {
    fmt.Printf("  -> REPORT external unwrapped: %s\n", origin.sig)
   } else {
    if cfg.ReportInternalErrors {
     fmt.Printf("  -> REPORT internal should be wrapped: %s\n", origin.sig)
    } else {
     fmt.Printf("  -> internal but not reporting\n")
    }
   }
  } else if origin != nil && origin.isIgnored {
   fmt.Printf("  -> ignored (isIgnored)\n")
  }
 }
case *ast.IfStmt:
 if s.Body != nil {
  processBlock(s.Body, info, cfg, env, curPkg)
 }
 if s.Else != nil {
  switch elseStmt := s.Else.(type) {
  case *ast.BlockStmt:
   processBlock(elseStmt, info, cfg, env, curPkg)
  case *ast.IfStmt:
   processStmt(elseStmt, info, cfg, env, curPkg)
  }
 }
case *ast.BlockStmt:
 processBlock(s, info, cfg, env, curPkg)
case *ast.ForStmt:
 if s.Body != nil {
  processBlock(s.Body, info, cfg, env, curPkg)
 }
case *ast.RangeStmt:
 if s.Body != nil {
  processBlock(s.Body, info, cfg, env, curPkg)
 }
}
}
