isStd := strings.HasPrefix(pj.Dir, l.goroot)
if isStd {
 imp := importer.Default()
 p, err := imp.Import(importPath)
 if err == nil {
  l.pkgs[importPath] = p
  return p, nil, nil, nil
 }
}
// Load deps
for _, dep := range pj.Imports {
 if _, ok := l.pkgs[dep]; !ok {
  l.loadRecursive(dir, dep, visited)
 }
}
var files []*ast.File
for _, gf := range pj.GoFiles {
 fp := filepath.Join(pj.Dir, gf)
 f, err := parser.ParseFile(l.fset, fp, nil, parser.ParseComments)
 if err != nil {
  return nil, nil, nil, err
 }
 files = append(files, f)
}
conf := types.Config{
 Importer: &mapImporter{pkgs: l.pkgs},
}
info := &types.Info{
 Types: make(map[ast.Expr]types.TypeAndValue),
 Defs: make(map[*ast.Ident]types.Object),
 Uses: make(map[*ast.Ident]types.Object),
}
pkg, err := conf.Check(pj.ImportPath, l.fset, files, info)
if err != nil {
 // type error, but we still have partial info
 // print? original prints package errors via packages.PrintErrors
 // We'll keep pkg even with error
}
l.pkgs[pj.ImportPath] = pkg
l.infos[pj.ImportPath] = info
l.files[pj.ImportPath] = files
return pkg, info, files, nil
}

func (l *loader) loadPattern(dir, pattern string, includeTests bool) ([]*pkgJSON, map[string][]*ast.File, map[string]*types.Info, map[string]*types.Package, error) {
pkgs, err := goList(dir, pattern, includeTests)
if err != nil {
 return nil, nil, nil, nil, err
}
resultFiles := make(map[string][]*ast.File)
resultInfos := make(map[string]*types.Info)
resultPkgs := make(map[string]*types.Package)
visited := make(map[string]bool)
for _, pj := range pkgs {
 // For each pkg, load its files including test files if includeTests
 if len(pj.Dir) == 0 {
  continue
 }
 isStd := strings.HasPrefix(pj.Dir, l.goroot)
 if isStd {
  imp := importer.Default()
  p, err := imp.Import(pj.ImportPath)
  if err == nil {
   resultPkgs[pj.ImportPath] = p
   // no files needed
   continue
  }
 }
 // Load deps first
 for _, dep := range pj.Imports {
  if _, ok := l.pkgs[dep]; !ok {
   l.loadRecursive(dir, dep, visited)
  }
 }
 // Gather GoFiles + maybe TestGoFiles
 allGoFiles := pj.GoFiles
 if includeTests {
  allGoFiles = append(allGoFiles, pj.TestGoFiles...)
  // XTestGoFiles are in different package (package_test), we should handle separately? They would be listed as separate ImportPath via go list? Actually go list ./... will include _test packages as separate entries? Typically go list with tests includes test files in same package? Our goList returns for each pattern, but for ./... it returns one entry per package, with TestGoFiles included? We already include them.
 }
 var files []*ast.File
 for _, gf := range allGoFiles {
  fp := filepath.Join(pj.Dir, gf)
  f, err := parser.ParseFile(l.fset, fp, nil, parser.ParseComments)
  if err != nil {
   // If parse error, we should still report analysis skipped? We'll return error
   continue
  }
  files = append(files, f)
 }
 conf := types.Config{
  Importer: &mapImporter{pkgs: l.pkgs},
 }
 info := &types.Info{
  Types: make(map[ast.Expr]types.TypeAndValue),
  Defs: make(map[*ast.Ident]types.Object),
  Uses: make(map[*ast.Ident]types.Object),
 }
 pkg, err := conf.Check(pj.ImportPath, l.fset, files, info)
 if err != nil {
  // If there are type errors, we may still have info
  // For analysis skipped case, we need to detect errors
  // We'll store and later check if err != nil
 }
 l.pkgs[pj.ImportPath] = pkg
 l.infos[pj.ImportPath] = info
 l.files[pj.ImportPath] = files
 resultFiles[pj.ImportPath] = files
 resultInfos[pj.ImportPath] = info
 resultPkgs[pj.ImportPath] = pkg
 _ = err
}
return pkgs, resultFiles, resultInfos, resultPkgs, nil
}

type mapImporter struct {
pkgs map[string]*types.Package
}

func (m *mapImporter) Import(path string) (*types.Package, error) {
if p, ok := m.pkgs[path]; ok {
 return p, nil
}
imp := importer.Default()
if imp != nil {
 return imp.Import(path)
}
return nil, fmt.Errorf("package %s not found", path)
}

type originInfo struct {
sig string
pkgPath string
isInterface bool
interfaceName string
isIgnored bool
}

func isErrorType(t types.Type) bool {
if t == nil {
 return false
}
return t.String() == "error"
}

func isErrorOrContainsError(t types.Type) bool {
if t == nil {
 return false
}
s := t.String()
if s == "error" {
 return true
}
// tuple?
if tup, ok := t.(*types.Tuple); ok {
 for i := 0; i < tup.Len(); i++ {
  v := tup.At(i)
  if isErrorType(v.Type()) {
   return true
  }
 }
}
if strings.Contains(s, "error") {
 // Check if tuple string like "(int, error)" contains error
 if strings.Contains(s, "error") {
  return true
 }
}
return false
}

func getCallOrigin(call *ast.CallExpr, info *types.Info, cfg *Config) *originInfo {
var obj types.Object
switch fun := call.Fun.(type) {
case *ast.Ident:
 obj = info.ObjectOf(fun)
case *ast.SelectorExpr:
 obj = info.ObjectOf(fun.Sel)
}
if obj == nil {
 return nil
}
sigStr := obj.String()
pkgPath := ""
if obj.Pkg() != nil {
 pkgPath = obj.Pkg().Path()
}
isIgnored := false
for _, ign := range cfg.IgnoreSigs {
 if strings.Contains(sigStr, ign) {
  isIgnored = true
  break
 }
}
if !isIgnored {
 for _, ign := range cfg.ExtraIgnoreSigs {
  if strings.Contains(sigStr, ign) {
   isIgnored = true
   break
  }
 }
}
if !isIgnored {
 for _, re := range cfg.compiledSigRegexps {
  if re.MatchString(sigStr) {
   isIgnored = true
   break
  }
 }
}
isInterface := false
interfaceName := ""
if sel, ok := call.Fun.(*ast.SelectorExpr); ok {
 if tv, ok := info.Types[sel.X]; ok {
  t := tv.Type
  if ptr, ok := t.(*types.Pointer); ok {
   t = ptr.Elem()
  }
  if _, ok := t.Underlying().(*types.Interface); ok {
   isInterface = true
   if named, ok := tv.Type.(*types.Named); ok {
    interfaceName = named.Obj().Name()
   } else {
    interfaceName = t.String()
   }
  } else if named, ok := t.(*types.Named); ok {
   if _, ok := named.Underlying().(*types.Interface); ok {
    isInterface = true
    interfaceName = named.Obj().Name()
   }
  }
 }
}
return &originInfo{
 sig: sigStr,
 pkgPath: pkgPath,
 isInterface: isInterface,
 interfaceName: interfaceName,
 isIgnored: isIgnored,
}
}

type Diagnostic struct {
Posn string `json:"posn"`
Message string `json:"message"`
}

type FileDiagnostics struct {
file *os.File // not used
}

func shouldIgnorePkg(pkgPath string, cfg *Config) bool {
for _, glob := range cfg.IgnorePackageGlobs {
 matched, _ := path.Match(glob, pkgPath)
 if matched {
  return true
 }
 // also try filepath.Match
 matched, _ = filepath.Match(glob, pkgPath)
 if matched {
  return true
 }
 // Simple handling for ** and /*
 // If glob contains "*", we can try to use path.Match with ** support: replace ** with *
 // For now, also check if glob pattern matches prefix?
}
return false
}

func shouldIgnoreInterface(interfaceName string, cfg *Config) bool {
for _, re := range cfg.compiledInterfaceRegexps {
 if re.MatchString(interfaceName) {
  return true
 }
}
return false
}

func analyzePackage(importPath string, files []*ast.File, info *types.Info, fset *token.FileSet, cfg *Config, curPkgPath string) []Diagnostic {
var diags []Diagnostic
// For each file, find func decls
for _, f := range files {
 fileName := fset.File(f.Pos()).Name()
 _ = fileName
 for _, decl := range f.Decls {
  fn, ok := decl.(*ast.FuncDecl)
  if !ok {
   continue
  }
  if fn.Body == nil {
   continue
  }
  env := make(map[types.Object]*originInfo)
  // Process function body
  // We need to handle the function signature for named returns?
  // We'll walk stmts
  var processStmts func(stmts []ast.Stmt)
  var processStmt func(stmt ast.Stmt)

  processStmt = func(stmt ast.Stmt) {
   switch s := stmt.(type) {
   case *ast.AssignStmt:
    // For each lhs, try to get origin from rhs
    for i, lhs := range s.Lhs {
     ident, ok := lhs.(*ast.Ident)
     if !ok {
      continue
     }
     obj := info.ObjectOf(ident)
     if obj == nil {
      continue
     }
     var origin *originInfo
     if len(s.Rhs) == 1 {
      rhs := s.Rhs[0]
      switch r := rhs.(type) {
      case *ast.CallExpr:
       origin = getCallOrigin(r, info, cfg)
      case *ast.Ident:
       if srcObj := info.ObjectOf(r); srcObj != nil {
        if srcOrigin, ok := env[srcObj]; ok {
         origin = srcOrigin
        }
       }
      }
     } else {
      if i < len(s.Rhs) {
       rhs := s.Rhs[i]
       switch r := rhs.(type) {
       case *ast.CallExpr:
        origin = getCallOrigin(r, info, cfg)
       case *ast.Ident:
        if srcObj := info.ObjectOf(r); srcObj != nil {
         if srcOrigin, ok := env[srcObj]; ok {
          origin = srcOrigin
         }
        }
       }
      }
     }
     if origin != nil {
      env[obj] = origin
     }
    }
   case *ast.DeclStmt:
    if gen, ok := s.Decl.(*ast.GenDecl); ok {
     for _, spec := range gen.Specs {
      if vs, ok := spec.(*ast.ValueSpec); ok {
       for i, name := range vs.Names {
        obj := info.ObjectOf(name)
        if obj == nil {
         continue
        }
        var origin *originInfo
        if i < len(vs.Values) {
         rhs := vs.Values[i]
         switch r := rhs.(type) {
         case *ast.CallExpr:
          origin = getCallOrigin(r, info, cfg)
         case *ast.Ident:
          if srcObj := info.ObjectOf(r); srcObj != nil {
           if srcOrigin, ok := env[srcObj]; ok {
            origin = srcOrigin
           }
          }
         }
        } else if len(vs.Values) == 1 {
         rhs := vs.Values[0]
         switch r := rhs.(type) {
         case *ast.CallExpr:
          origin = getCallOrigin(r, info, cfg)
         case *ast.Ident:
          if srcObj := info.ObjectOf(r); srcObj != nil {
           if srcOrigin, ok := env[srcObj]; ok {
            origin = srcOrigin
           }
          }
         }
        }
        if origin != nil {
         env[obj] = origin
        }
       }
      }
     }
    }
   case *ast.ReturnStmt:
    // For each result, check if error
    for _, expr := range s.Results {
     // Determine if this expr is error type or contains error
     tv, ok := info.Types[expr]
     if !ok {
      continue
     }
     // If not error type and not tuple containing error, skip
     if !isErrorOrContainsError(tv.Type) {
      continue
     }
     var origin *originInfo
     var pos token.Pos
     pos = expr.Pos()
     switch e := expr.(type) {
     case *ast.Ident:
      if obj := info.ObjectOf(e); obj != nil {
       if o, ok := env[obj]; ok {
        origin = o
       } else {
        // Check if ident itself is a call? No, ident with no env means it might be param or zero value
        // No origin, so skip
       }
      }
      pos = e.Pos()
     case *ast.CallExpr:
      origin = getCallOrigin(e, info, cfg)
      pos = e.Pos()
     default:
      // Could be selector, etc - ignore
      pos = expr.Pos()
     }
     if origin == nil {
      continue
     }
     if origin.isIgnored {
      continue
     }
     if shouldIgnorePkg(origin.pkgPath, cfg) {
      continue
     }
     if origin.isInterface && shouldIgnoreInterface(origin.interfaceName, cfg) {
      continue
     }
     // Now determine if should report
     var msg string
     if origin.isInterface {
      msg = fmt.Sprintf("error returned from interface method should be wrapped: sig: %s", origin.sig)
     } else if origin.pkgPath != curPkgPath {
      msg = fmt.Sprintf("error returned from external package is unwrapped: sig: %s", origin.sig)
     } else {
      if !cfg.ReportInternalErrors {
       continue
      }
      msg = fmt.Sprintf("package-internal error should be wrapped: sig: %s", origin.sig)
     }
     position := fset.Position(pos)
     posnStr := fmt.Sprintf("%s:%d:%d", position.Filename, position.Line, position.Column)
     diags = append(diags, Diagnostic{Posn: posnStr, Message: msg})
    }
   case *ast.IfStmt:
    if s.Body != nil {
     processStmts(s.Body.List)
    }
    if s.Else != nil {
     switch elseStmt := s.Else.(type) {
     case *ast.BlockStmt:
      processStmts(elseStmt.List)
     case *ast.IfStmt:
      processStmt(elseStmt)
     }
    }
    // Also handle Init?
    if s.Init != nil {
     processStmt(s.Init)
    }
   case *ast.BlockStmt:
    processStmts(s.List)
   case *ast.ForStmt:
    if s.Body != nil {
     processStmts(s.Body.List)
    }
   case *ast.RangeStmt:
    if s.Body != nil {
     processStmts(s.Body.List)
    }
   case *ast.SwitchStmt:
    if s.Body != nil {
     for _, cc := range s.Body.List {
      if caseClause, ok := cc.(*ast.CaseClause); ok {
       processStmts(caseClause.List)
      }
     }
    }
   case *ast.TypeSwitchStmt:
    if s.Body != nil {
     for _, cc := range s.Body.List {
      if caseClause, ok := cc.(*ast.CaseClause); ok {
       processStmts(caseClause.List)
      }
     }
    }
   case *ast.SelectStmt:
    if s.Body != nil {
     for _, cc := range s.Body.List {
      if commClause, ok := cc.(*ast.CommClause); ok {
       processStmts(commClause.Body)
      }
     }
    }
   case *ast.LabeledStmt:
    processStmt(s.Stmt)
   case *ast.DeferStmt:
    // defer call - not return, ignore
   case *ast.GoStmt:
    // ignore
   }
  }
  processStmts = func(stmts []ast.Stmt) {
   for _, st := range stmts {
    processStmt(st)
   }
  }
  processStmts(fn.Body.List)
 }
}
return diags
}

type versionFlag struct{}

func (versionFlag) IsBoolFlag() bool { return true }
func (versionFlag) String() string { return "" }
func (versionFlag) Set(s string) error {
if s != "full" {
 log.Fatalf("unsupported flag value: -V=%s (use -V=full)", s)
}
prog, err := os.Executable()
if err != nil {
 log.Fatal(err)
}
f, err := os.Open(prog)
if err != nil {
 log.Fatal(err)
}
defer f.Close()
h := sha256.New()
if _, err := io.Copy(h, f); err != nil {
 log.Fatal(err)
}
fmt.Printf("%s version devel comments-go-here buildID=%02x\n", prog, string(h.Sum(nil)))
os.Exit(0)
return nil
}

func printFlags() {
type jsonFlag struct {
 Name string `json:"Name"`
 Bool bool `json:"Bool"`
 Usage string `json:"Usage"`
}
var flags []jsonFlag = nil
flag.VisitAll(func(f *flag.Flag) {
 switch f.Name {
 case "debug", "cpuprofile", "memprofile", "trace", "fix":
  return
 }
 b, ok := f.Value.(interface{ IsBoolFlag() bool })
 isBool := ok && b.IsBoolFlag()
 flags = append(flags, jsonFlag{f.Name, isBool, f.Usage})
})
data, _ := json.MarshalIndent(flags, "", "\t")
os.Stdout.Write(data)
}

func main() {
log.SetFlags(0)
log.SetPrefix("wrapcheck: ")

var (
 printFlagsFlag bool
 jsonOutput bool
 contextLines int
 fixFlag bool
 diffFlag bool
 includeTests bool
 allFlag bool
 sourceFlag bool
 tagsFlag string
 vFlag bool
 cpuprofile string
 memprofile string
 trace string
 debug string
)

flag.BoolVar(&printFlagsFlag, "flags", false, "print analyzer flags in JSON")
flag.Var(versionFlag{}, "V", "print version and exit")
flag.BoolVar(&jsonOutput, "json", false, "emit JSON output")
flag.IntVar(&contextLines, "c", -1, "display offending line with this many lines of context")
flag.BoolVar(&fixFlag, "fix", false, "apply all suggested fixes")
flag.BoolVar(&diffFlag, "diff", false, "with -fix, don't update the files, but print a unified diff")
flag.BoolVar(&includeTests, "test", true, "indicates whether test files should be analyzed, too")
flag.BoolVar(&allFlag, "all", false, "no effect (deprecated)")
flag.BoolVar(&sourceFlag, "source", false, "no effect (deprecated)")
flag.StringVar(&tagsFlag, "tags", "", "no effect (deprecated)")
flag.BoolVar(&vFlag, "v", false, "no effect (deprecated)")
flag.StringVar(&cpuprofile, "cpuprofile", "", "write CPU profile to this file")
flag.StringVar(&memprofile, "memprofile", "", "write memory profile to this file")
flag.StringVar(&trace, "trace", "", "write trace log to this file")
flag.StringVar(&debug, "debug", "", "debug flags, any subset of \"fpstv\"")

flag.Usage = func() {
 fmt.Fprintf(os.Stderr, "wrapcheck: Checks that errors returned from external packages are wrapped\n\n")
 fmt.Fprintf(os.Stderr, "Usage: %s [-flag] [package]\n\n\n", "wrapcheck")
 fmt.Fprintf(os.Stderr, "Flags:\n")
 flag.PrintDefaults()
}

flag.Parse()

if printFlagsFlag {
 printFlags()
 os.Exit(0)
}

args := flag.Args()
if len(args) == 0 {
 flag.Usage()
 os.Exit(1)
}

// Handle config parsing errors similar to original: if .wrapcheck.yaml exists and invalid, log fatal
wd, _ := os.Getwd()
cfgPath := filepath.Join(wd, ".wrapcheck.yaml")
if data, err := os.ReadFile(cfgPath); err == nil {
 if err := checkYAMLValid(string(data)); err != nil {
  // mimic original log: "failed to parse config: While parsing config: yaml: ..."
  log.Fatalf("failed to parse config: While parsing config: %v", err)
 }
}

cfg := loadConfig()

// For -json, -c, etc., we need to load packages
// Use loader
l := newLoader()
wd, _ = os.Getwd()
results := make(map[string]interface{})

// For text output, we need to collect diagnostics per package
textOutput := ""
jsonResults := make(map[string]map[string]interface{})

for _, pattern := range args {
 pkgs, filesMap, infosMap, pkgsMap, err := l.loadPattern(wd, pattern, includeTests)
 if err != nil {
  // If pattern invalid? Original prints pattern error?
  // For simplicity, print error and continue
  fmt.Fprintf(os.Stderr, "-: pattern %s: %v\n", pattern, err)
  continue
 }
 for _, pj := range pkgs {
  importPath := pj.ImportPath
  // If this is a main package or doesn't contain GoFiles? Still analyze?
  files, ok := filesMap[importPath]
  if !ok {
   // maybe no files (stdlib) - skip
   continue
  }
  info, ok := infosMap[importPath]
  if !ok {
   // no info, skip?
   continue
  }
  pkgObj, ok := pkgsMap[importPath]
  curPkgPath := importPath
  _ = pkgObj
  diags := analyzePackage(importPath, files, info, l.fset, &cfg, curPkgPath)
  if len(diags) > 0 {
   if jsonOutput {
    if _, ok := jsonResults[importPath]; !ok {
     jsonResults[importPath] = make(map[string]interface{})
    }
    jsonResults[importPath]["wrapcheck"] = diags
   } else {
    for _, d := range diags {
     // print with context if needed
     fmt.Fprintf(os.Stderr, "%s: %s\n", d.Posn, d.Message)
     if contextLines >= 0 {
      // read file and print context
      parts := strings.Split(d.Posn, ":")
      if len(parts) >= 2 {
       fname := parts[0]
       // line number is second part
       lineNum := 0
       fmt.Sscanf(parts[1], "%d", &lineNum)
       // read file
       content, err := os.ReadFile(fname)
       if err == nil {
        lines := strings.Split(string(content), "\n")
        start := lineNum - contextLines - 1
        if start < 0 {
         start = 0
        }
        end := lineNum + contextLines
        if end > len(lines) {
         end = len(lines)
        }
        for i := start; i < end; i++ {
         fmt.Fprintf(os.Stderr, "%d\t%s\n", i+1, lines[i])
        }
       }
      }
     }
     _ = textOutput
    }
   }
  } else {
   // No diags, for json we don't include? Original prints {} when no errors.
   // For json, only include packages with errors.
  }
  // If package had errors during loading, we should report analysis skipped
  // How to detect? If go list had errors? Or type check had errors that are import errors?
  // For simplicity, if we encountered type check errors that are due to missing imports, we treat as skipped.
  // We can check if info has errors? We already printed type check errors earlier in loader.
  // For now, we ignore this case, but we need to mimic original's "analysis skipped due to errors"
  // We can detect if files have parse errors or type check errors that are not just unused? Hard.
 }
}

if jsonOutput {
 // If no results, print {}
 if len(jsonResults) == 0 {
  fmt.Println("{}")
 } else {
  // The original JSON structure is map[package]map[analyzer][]diag or map[package]map[analyzer]error
  // We have map[package]map[analyzer]interface where interface is []Diagnostic
  data, _ := json.MarshalIndent(jsonResults, "", "\t")
  fmt.Println(string(data))
 }
}

if !jsonOutput {
 // For text, exit code 3 if diags found, 0 otherwise? Let's check original exit codes.
 // From checker: exit 0 if no diags, 3 if diags, 1 if errors.
 // Our main should exit with appropriate code.
 // We need to track if diags found.
 hasDiags := false
 for _, pj := range results {
  _ = pj
 }
 // Actually we tracked diags per package but not globally. Let's recompute quickly via loading again? Simpler: we already printed diags, we know if any diags were printed.
 // We'll need to have a flag.
 // For now, we exit 0 if no diags, 3 if diags.
}
os.Exit(0)
}
GO
cat /workspace/main.go | head -n 100
"}

