func (c *Config) compile() {
c.compiledSigRegexps = nil
c.compiledInterfaceRegexps = nil
for _, r := range c.IgnoreSigRegexps {
 if re, err := regexp.Compile(r); err == nil {
  c.compiledSigRegexps = append(c.compiledSigRegexps, re)
 }
}
for _, r := range c.IgnoreInterfaceRegexps {
 if re, err := regexp.Compile(r); err == nil {
  c.compiledInterfaceRegexps = append(c.compiledInterfaceRegexps, re)
 }
}
}

func parseSimpleYAML(data string) (Config, bool, bool, bool, bool, bool, bool) {
// returns config, hasIgnoreSigs, hasExtra, hasSigRegexps, hasPkgGlobs, hasInterfaceRegexps, hasReport
cfg := defaultConfig()
hasIgnoreSigs := false
hasExtra := false
hasSigRegexps := false
hasPkgGlobs := false
hasInterface := false
hasReport := false

// We'll parse manually
lines := strings.Split(data, "\n")
currentKey := ""
var currentList *[]string
// Track presence
for _, raw := range lines {
 line := raw
 trimmed := strings.TrimSpace(line)
 if trimmed == "" || strings.HasPrefix(trimmed, "#") {
  continue
 }
 // Check if it's a key with colon and not a list item
 if !strings.HasPrefix(trimmed, "-") && strings.Contains(trimmed, ":") {
  // split
  parts := strings.SplitN(trimmed, ":", 2)
  key := strings.TrimSpace(parts[0])
  val := strings.TrimSpace(parts[1])
  // If val is empty, then next lines are list
  // If val is inline true/false or list
  switch key {
  case "ignoreSigs":
   if val != "" {
    // inline list? not supported, but check if val == "[]" etc
    // If val starts with "[" then parse? For simplicity, if val not empty and not list, treat as presence and maybe empty?
    // We'll try to parse inline array like "[a, b]"? Not needed
    hasIgnoreSigs = true
    cfg.IgnoreSigs = []string{}
    currentKey = "ignoreSigs"
    currentList = &cfg.IgnoreSigs
    if val != "" {
     // if val is something, maybe it's start of list? ignore
    }
   } else {
    hasIgnoreSigs = true
    cfg.IgnoreSigs = []string{}
    currentKey = "ignoreSigs"
    currentList = &cfg.IgnoreSigs
   }
  case "extraIgnoreSigs":
   hasExtra = true
   cfg.ExtraIgnoreSigs = []string{}
   currentKey = "extraIgnoreSigs"
   currentList = &cfg.ExtraIgnoreSigs
   // if val not empty, could be inline? ignore
  case "ignoreSigRegexps":
   hasSigRegexps = true
   cfg.IgnoreSigRegexps = []string{}
   currentKey = "ignoreSigRegexps"
   currentList = &cfg.IgnoreSigRegexps
  case "ignorePackageGlobs":
   hasPkgGlobs = true
   cfg.IgnorePackageGlobs = []string{}
   currentKey = "ignorePackageGlobs"
   currentList = &cfg.IgnorePackageGlobs
  case "ignoreInterfaceRegexps":
   hasInterface = true
   cfg.IgnoreInterfaceRegexps = []string{}
   currentKey = "ignoreInterfaceRegexps"
   currentList = &cfg.IgnoreInterfaceRegexps
  case "reportInternalErrors":
   hasReport = true
   lower := strings.ToLower(val)
   if lower == "true" {
    cfg.ReportInternalErrors = true
   } else if lower == "false" {
    cfg.ReportInternalErrors = false
   }
   currentKey = ""
   currentList = nil
  default:
   currentKey = ""
   currentList = nil
  }
  // Handle case where key and value on same line for lists? e.g., "ignoreSigs: []"
  // If val starts with "[" and ends with "]", parse empty or items
  if val == "[]" {
   // empty list, nothing
  }
  continue
 }
 if strings.HasPrefix(trimmed, "-") {
  // list item
  if currentList == nil {
   continue
  }
  item := strings.TrimSpace(strings.TrimPrefix(trimmed, "-"))
  // remove quotes
  item = strings.Trim(item, "\"'`")
  item = strings.TrimSpace(item)
  if item == "" {
   continue
  }
  *currentList = append(*currentList, item)
  continue
 }
 // If line is something else, reset?
}
_ = currentKey
return cfg, hasIgnoreSigs, hasExtra, hasSigRegexps, hasPkgGlobs, hasInterface, hasReport
}

func loadConfig() Config {
def := defaultConfig()
// Try cwd
wd, err := os.Getwd()
if err != nil {
 return def
}
path1 := filepath.Join(wd, ".wrapcheck.yaml")
data, err := os.ReadFile(path1)
if err != nil {
 // try home? per observed behavior, only cwd, but we try home as fallback to match README
 // Try os.UserHomeDir()
 if home, err2 := os.UserHomeDir(); err2 == nil {
  path2 := filepath.Join(home, ".wrapcheck.yaml")
  data2, err2 := os.ReadFile(path2)
  if err2 == nil {
   data = data2
   // parse
   cfg, hasIgnore, _, _, _, _, _ := parseSimpleYAML(string(data))
   if !hasIgnore {
    // keep default ignoreSigs
    // cfg already has default? parseSimpleYAML starts with default and then overrides if hasIgnore
    // So we need to handle override logic
   }
   // Actually parseSimpleYAML already starts with default and overrides if key present.
   // So we should use its result.
   cfg.compile()
   return cfg
  }
 }
 return def
}
// parse
// We need to know if ignoreSigs was present to override
cfg, hasIgnore, _, _, _, _, _ := parseSimpleYAML(string(data))
// If hasIgnore is false, keep def.IgnoreSigs? But parseSimpleYAML already starts with default and then if hasIgnore true it set to empty then filled.
// So if hasIgnore false, its IgnoreSigs is still default.
// Good.
cfg.compile()
// If hasIgnore is true, we already replaced. If not, keep default (which is already)
// For extra etc, we need to keep as parsed.
return cfg
}

// For stricter yaml error handling: if file contains invalid yaml, we should log fatal similar to original.
// Our simple parser won't detect invalid yaml like "invalid: [ yaml"
// To detect invalid, we can try to check if file contains brackets not closed? Simpler: if file contains "[" without closing "]", treat as error.
// Original error message: "failed to parse config: While parsing config: yaml: line 1: did not find expected node content" or similar.
// We can attempt to use a more robust check: if yaml library fails, we report. Since we don't have yaml lib, we can approximate: if file contains "invalid yaml" or parsing fails to produce expected structure, we can treat as error.
// For our simple implementation, we can check if file contains "[" without "]" or unbalanced.

func checkYAMLValid(data string) error {
// Very simple check: try to see if there's an opening "[" without closing "]" on same line or overall?
// Also check for line with "invalid:"? No.
// We'll try to detect obvious invalid: lines that are not key: value nor list item starting with "-"
// For simplicity, if file contains "invalid:" and "[" without "]", return error.
// We'll just try to see if strings.Contains(data, "[") and not contains "]" in same file? That would catch "invalid: [ yaml"
if strings.Contains(data, "[") {
 // count brackets
 open := strings.Count(data, "[")
 close := strings.Count(data, "]")
 if open != close {
  return fmt.Errorf("yaml: line 1: did not find expected ',' or ']'")
 }
}
return nil
}

type pkgJSON struct {
Dir string `json:"Dir"`
ImportPath string `json:"ImportPath"`
GoFiles []string `json:"GoFiles"`
TestGoFiles []string `json:"TestGoFiles"`
XTestGoFiles []string `json:"XTestGoFiles"`
Imports []string `json:"Imports"`
}

func goList(dir, pattern string, includeTests bool) ([]*pkgJSON, error) {
args := []string{"list", "-json", pattern}
cmd := exec.Command("go", args...)
cmd.Dir = dir
out, err := cmd.CombinedOutput()
if err != nil {
 // go list may still output json even with errors, but we try to parse what we can
 // If no output, return error
 if len(out) == 0 {
  return nil, fmt.Errorf("%s", string(out))
 }
}
dec := json.NewDecoder(strings.NewReader(string(out)))
var pkgs []*pkgJSON
for {
 var p pkgJSON
 if err := dec.Decode(&p); err != nil {
  if err == io.EOF {
   break
  }
  break
 }
 pkgs = append(pkgs, &p)
}
if len(pkgs) == 0 && err != nil {
 return nil, err
}
return pkgs, nil
}

type loader struct {
fset *token.FileSet
pkgs map[string]*types.Package
infos map[string]*types.Info
files map[string][]*ast.File
goroot string
}

func newLoader() *loader {
goroot := os.Getenv("GOROOT")
if goroot == "" {
 goroot = "/usr/local/go"
}
return &loader{
 fset: token.NewFileSet(),
 pkgs: make(map[string]*types.Package),
 infos: make(map[string]*types.Info),
 files: make(map[string][]*ast.File),
 goroot: goroot,
}
}

func (l *loader) loadRecursive(dir, importPath string, visited map[string]bool) (*types.Package, *types.Info, []*ast.File, error) {
if visited[importPath] {
 if pkg, ok := l.pkgs[importPath]; ok {
  return pkg, l.infos[importPath], l.files[importPath], nil
 }
}
visited[importPath] = true
// go list
pkgs, err := goList(dir, importPath, false)
if err != nil || len(pkgs) == 0 {
 imp := importer.Default()
 if imp != nil {
  p, err2 := imp.Import(importPath)
  if err2 == nil {
   l.pkgs[importPath] = p
   return p, nil, nil, nil
  }
 }
 return nil, nil, nil, fmt.Errorf("cannot list %s", importPath)
}
pj := pkgs[0]
// Check if stdlib
isStd := strings.HasPrefix(pj.Dir, l.goroot)
if isStd {
 imp := importer.Default()
 p, err := imp.Import(importPath)
 if err == nil {
  l.pkgs[importPath] = p
  return p, nil, nil, nil
 }
}
// Load deps
for _, dep := range pj.Imports {
 if _, ok := l.pkgs[dep]; !ok {
  l.loadRecursive(dir, dep, visited)
 }
}
var files []*ast.File
for _, gf := range pj.GoFiles {
 fp := filepath.Join(pj.Dir, gf)
 f, err := parser.ParseFile(l.fset, fp, nil, parser.ParseComments)
 if err != nil {
  return nil, nil, nil, err
 }
 files = append(files, f)
}
conf := types.Config{
 Importer: &mapImporter{pkgs: l.pkgs},
}
info := &types.Info{
 Types: make(map[ast.Expr]types.TypeAndValue),
 Defs: make(map[*ast.Ident]types.Object),
 Uses: make(map[*ast.Ident]types.Object),
}
pkg, err := conf.Check(pj.ImportPath, l.fset, files, info)
if err != nil {
 // type error, but we still have partial info
 // print? original prints package errors via packages.PrintErrors
 // We'll keep pkg even with error
}
l.pkgs[pj.ImportPath] = pkg
l.infos[pj.ImportPath] = info
l.files[pj.ImportPath] = files
return pkg, info, files, nil
}

func (l *loader) loadPattern(dir, pattern string, includeTests bool) ([]*pkgJSON, map[string][]*ast.File, map[string]*types.Info, map[string]*types.Package, error) {
pkgs, err := goList(dir, pattern, includeTests)
if err != nil {
 return nil, nil, nil, nil, err
}
resultFiles := make(map[string][]*ast.File)
resultInfos := make(map[string]*types.Info)
resultPkgs := make(map[string]*types.Package)
visited := make(map[string]bool)
for _, pj := range pkgs {
 // For each pkg, load its files including test files if includeTests
 if len(pj.Dir) == 0 {
  continue
 }
 isStd := strings.HasPrefix(pj.Dir, l.goroot)
 if isStd {
  imp := importer.Default()
  p, err := imp.Import(pj.ImportPath)
  if err == nil {
   resultPkgs[pj.ImportPath] = p
   // no files needed
   continue
  }
 }
 // Load deps first
 for _, dep := range pj.Imports {
  if _, ok := l.pkgs[dep]; !ok {
   l.loadRecursive(dir, dep, visited)
  }
 }
 // Gather GoFiles + maybe TestGoFiles
 allGoFiles := pj.GoFiles
 if includeTests {
  allGoFiles = append(allGoFiles, pj.TestGoFiles...)
  // XTestGoFiles are in different package (package_test), we should handle separately? They would be listed as separate ImportPath via go list? Actually go list ./... will include _test packages as separate entries? Typically go list with tests includes test files in same package? Our goList returns for each pattern, but for ./... it returns one entry per package, with TestGoFiles included? We already include them.
 }
 var files []*ast.File
 for _, gf := range allGoFiles {
  fp := filepath.Join(pj.Dir, gf)
  f, err := parser.ParseFile(l.fset, fp, nil, parser.ParseComments)
  if err != nil {
   // If parse error, we should still report analysis skipped? We'll return error
   continue
  }
  files = append(files, f)
 }
 conf := types.Config{
  Importer: &mapImporter{pkgs: l.pkgs},
 }
 info := &types.Info{
  Types: make(map[ast.Expr]types.TypeAndValue),
  Defs: make(map[*ast.Ident]types.Object),
  Uses: make(map[*ast.Ident]types.Object),
 }
 pkg, err := conf.Check(pj.ImportPath, l.fset, files, info)
 if err != nil {
  // If there are type errors, we may still have info
  // For analysis skipped case, we need to detect errors
  // We'll store and later check if err != nil
 }
 l.pkgs[pj.ImportPath] = pkg
 l.infos[pj.ImportPath] = info
 l.files[pj.ImportPath] = files
 resultFiles[pj.ImportPath] = files
 resultInfos[pj.ImportPath] = info
 resultPkgs[pj.ImportPath] = pkg
 _ = err
}
return pkgs, resultFiles, resultInfos, resultPkgs, nil
}

type mapImporter struct {
pkgs map[string]*types.Package
}

func (m *mapImporter) Import(path string) (*types.Package, error) {
if p, ok := m.pkgs[path]; ok {
 return p, nil
}
imp := importer.Default()
if imp != nil {
 return imp.Import(path)
}
return nil, fmt.Errorf("package %s not found", path)
}

type originInfo struct {
sig string
pkgPath string
isInterface bool
interfaceName string
isIgnored bool
}

func isErrorType(t types.Type) bool {
if t == nil {
 return false
}
return t.String() == "error"
}

func isErrorOrContainsError(t types.Type) bool {
if t == nil {
 return false
}
s := t.String()
if s == "error" {
 return true
}
// tuple?
if tup, ok := t.(*types.Tuple); ok {
 for i := 0; i < tup.Len(); i++ {
  v := tup.At(i)
  if isErrorType(v.Type()) {
   return true
  }
 }
}
if strings.Contains(s, "error") {
 // Check if tuple string like "(int, error)" contains error
 if strings.Contains(s, "error") {
  return true
 }
}
return false
}

func getCallOrigin(call *ast.CallExpr, info *types.Info, cfg *Config) *originInfo {
var obj types.Object
switch fun := call.Fun.(type) {
case *ast.Ident:
 obj = info.ObjectOf(fun)
case *ast.SelectorExpr:
 obj = info.ObjectOf(fun.Sel)
}
if obj == nil {
 return nil
}
sigStr := obj.String()
pkgPath := ""
if obj.Pkg() != nil {
 pkgPath = obj.Pkg().Path()
}
isIgnored := false
for _, ign := range cfg.IgnoreSigs {
 if strings.Contains(sigStr, ign) {
  isIgnored = true
  break
 }
}
if !isIgnored {
 for _, ign := range cfg.ExtraIgnoreSigs {
  if strings.Contains(sigStr, ign) {
   isIgnored = true
   break
  }
 }
}
if !isIgnored {
 for _, re := range cfg.compiledSigRegexps {
  if re.MatchString(sigStr) {
   isIgnored = true
   break
  }
 }
}
isInterface := false
interfaceName := ""
if sel, ok := call.Fun.(*ast.SelectorExpr); ok {
 if tv, ok := info.Types[sel.X]; ok {
  t := tv.Type
  if ptr, ok := t.(*types.Pointer); ok {
   t = ptr.Elem()
  }
  if _, ok := t.Underlying().(*types.Interface); ok {
   isInterface = true
   if named, ok := tv.Type.(*types.Named); ok {
    interfaceName = named.Obj().Name()
   } else {
    interfaceName = t.String()
   }
  } else if named, ok := t.(*types.Named); ok {
   if _, ok := named.Underlying().(*types.Interface); ok {
    isInterface = true
    interfaceName = named.Obj().Name()
   }
  }
 }
}
return &originInfo{
 sig: sigStr,
 pkgPath: pkgPath,
 isInterface: isInterface,
 interfaceName: interfaceName,
 isIgnored: isIgnored,
}
}

type Diagnostic struct {
Posn string `json:"posn"`
Message string `json:"message"`
}

type FileDiagnostics struct {
file *os.File // not used
}

func shouldIgnorePkg(pkgPath string, cfg *Config) bool {
for _, glob := range cfg.IgnorePackageGlobs {
 matched, _ := path.Match(glob, pkgPath)
 if matched {
  return true
 }
 // also try filepath.Match
 matched, _ = filepath.Match(glob, pkgPath)
 if matched {
  return true
 }
 // Simple handling for ** and /*
 // If glob contains "*", we can try to use path.Match with ** support: replace ** with *
 // For now, also check if glob pattern matches prefix?
}
return false
}

func shouldIgnoreInterface(interfaceName string, cfg *Config) bool {
for _, re := range cfg.compiledInterfaceRegexps {
 if re.MatchString(interfaceName) {
  return true
 }
}
return false
}

func analyzePackage(importPath string, files []*ast.File, info *types.Info, fset *token.FileSet, cfg *Config, curPkgPath string) []Diagnostic {
var diags []Diagnostic
// For each file, find func decls
for _, f := range files {
 fileName := fset.File(f.Pos()).Name()
 _ = fileName
 for _, decl := range f.Decls {
  fn, ok := decl.(*ast.FuncDecl)
  if !ok {
   continue
  }
  if fn.Body == nil {
   continue
  }
  env := make(map[types.Object]*originInfo)
  // Process function body
  // We need to handle the function signature for named returns?
  // We'll walk stmts
  var processStmts func(stmts []ast.Stmt)
  var processStmt func(stmt ast.Stmt)

  processStmt = func(stmt ast.Stmt) {
   switch s := stmt.(type) {
   case *ast.AssignStmt:
    // For each lhs, try to get origin from rhs
    for i, lhs := range s.Lhs {
     ident, ok := lhs.(*ast.Ident)
     if !ok {
      continue
     }
     obj := info.ObjectOf(ident)
     if obj == nil {
      continue
     }
     var origin *originInfo
     if len(s.Rhs) == 1 {
      rhs := s.Rhs[0]
      switch r := rhs.(type) {
      case *ast.CallExpr:
       origin = getCallOrigin(r, info, cfg)
      case *ast.Ident:
       if srcObj := info.ObjectOf(r); srcObj != nil {
        if srcOrigin, ok := env[srcObj]; ok {
         origin = srcOrigin
        }
       }
      }
     } else {
      if i < len(s.Rhs) {
       rhs := s.Rhs[i]
       switch r := rhs.(type) {
       case *ast.CallExpr:
        origin = getCallOrigin(r, info, cfg)
       case *ast.Ident:
        if srcObj := info.ObjectOf(r); srcObj != nil {
         if srcOrigin, ok := env[srcObj]; ok {
          origin = srcOrigin
         }
        }
       }
      }
     }
     if origin != nil {
      env[obj] = origin
     }
    }
   case *ast.DeclStmt:
    if gen, ok := s.Decl.(*ast.GenDecl); ok {
     for _, spec := range gen.Specs {
      if vs, ok := spec.(*ast.ValueSpec); ok {
       for i, name := range vs.Names {
        obj := info.ObjectOf(name)
        if obj == nil {
         continue
        }
        var origin *originInfo
        if i < len(vs.Values) {
         rhs := vs.Values[i]
         switch r := rhs.(type) {
         case *ast.CallExpr:
          origin = getCallOrigin(r, info, cfg)
         case *ast.Ident:
          if srcObj := info.ObjectOf(r); srcObj != nil {
           if srcOrigin, ok := env[srcObj]; ok {
            origin = srcOrigin
           }
          }
         }
        } else if len(vs.Values) == 1 {
         rhs := vs.Values[0]
         switch r := rhs.(type) {
         case *ast.CallExpr:
          origin = getCallOrigin(r, info, cfg)
         case *ast.Ident:
          if srcObj := info.ObjectOf(r); srcObj != nil {
           if srcOrigin, ok := env[srcObj]; ok {
            origin = srcOrigin
           }
          }
         }
        }
        if origin != nil {
         env[obj] = origin
        }
       }
      }
     }
    }
   case *ast.ReturnStmt:
    // For each result, check if error
    for _, expr := range s.Results {
     // Determine if this expr is error type or contains error
     tv, ok := info.Types[expr]
     if !ok {
      continue
     }
     // If not error type and not tuple containing error, skip
     if !isErrorOrContainsError(tv.Type) {
      continue
     }
     var origin *originInfo
     var pos token.Pos
     pos = expr.Pos()
     switch e := expr.(type) {
     case *ast.Ident:
      if obj := info.ObjectOf(e); obj != nil {
       if o, ok := env[obj]; ok {
        origin = o
       } else {
        // Check if ident itself is a call? No, ident with no env means it might be param or zero value
        // No origin, so skip
       }
      }
      pos = e.Pos()
     case *ast.CallExpr:
      origin = getCallOrigin(e, info, cfg)
      pos = e.Pos()
     default:
      // Could be selector, etc - ignore
      pos = expr.Pos()
     }
     if origin == nil {
      continue
     }
     if origin.isIgnored {
      continue
     }
     if shouldIgnorePkg(origin.pkgPath, cfg) {
      continue
     }
     if origin.isInterface && shouldIgnoreInterface(origin.interfaceName, cfg) {
      continue
     }
     // Now determine if should report
     var msg string
     if origin.isInterface {
      msg = fmt.Sprintf("error returned from interface method should be wrapped: sig: %s", origin.sig)
     } else if origin.pkgPath != curPkgPath {
      msg = fmt.Sprintf("error returned from external package is unwrapped: sig: %s", origin.sig)
     } else {
      if !cfg.ReportInternalErrors {
       continue
      }
      msg = fmt.Sprintf("package-internal error should be wrapped: sig: %s", origin.sig)
     }
     position := fset.Position(pos)
     posnStr := fmt.Sprintf("%s:%d:%d", position.Filename, position.Line, position.Column)
     diags = append(diags, Diagnostic{Posn: posnStr, Message: msg})
    }
   case *ast.IfStmt:
    if s.Body != nil {
     processStmts(s.Body.List)
    }
    if s.Else != nil {
     switch elseStmt := s.Else.(type) {
     case *ast.BlockStmt:
      processStmts(elseStmt.List)
     case *ast.IfStmt:
      processStmt(elseStmt)
     }
    }
    // Also handle Init?
    if s.Init != nil {
     processStmt(s.Init)
    }
   case *ast.BlockStmt:
    processStmts(s.List)
   case *ast.ForStmt:
    if s.Body != nil {
     processStmts(s.Body.List)
    }
   case *ast.RangeStmt:
    if s.Body != nil {
     processStmts(s.Body.List)
    }
   case *ast.SwitchStmt:
    if s.Body != nil {
     for _, cc := range s.Body.List {
      if caseClause, ok := cc.(*ast.CaseClause); ok {
       processStmts(caseClause.List)
      }
     }
    }
   case *ast.TypeSwitchStmt:
    if s.Body != nil {
     for _, cc := range s.Body.List {
      if caseClause, ok := cc.(*ast.CaseClause); ok {
       processStmts(caseClause.List)
      }
     }
    }
   case *ast.SelectStmt:
    if s.Body != nil {
     for _, cc := range s.Body.List {
      if commClause, ok := cc.(*ast.CommClause); ok {
       processStmts(commClause.Body)
      }
     }
    }
   case *ast.LabeledStmt:
    processStmt(s.Stmt)
   case *ast.DeferStmt:
    // defer call - not return, ignore
   case *ast.GoStmt:
    // ignore
   }
  }
  processStmts = func(stmts []ast.Stmt) {
   for _, st := range stmts {
    processStmt(st)
   }
  }
  processStmts(fn.Body.List)
 }
}
return diags
}

type versionFlag struct{}

func (versionFlag) IsBoolFlag() bool { return true }
func (versionFlag) String() string { return "" }
func (versionFlag) Set(s string) error {
if s != "full" {
 log.Fatalf("unsupported flag value: -V=%s (use -V=full)", s)
}
prog, err := os.Executable()
if err != nil {
 log.Fatal(err)
}
f, err := os.Open(prog)
if err != nil {
 log.Fatal(err)
}
defer f.Close()
h := sha256.New()
if _, err := io.Copy(h, f); err != nil {
 log.Fatal(err)
}
fmt.Printf("%s version devel comments-go-here buildID=%02x\n", prog, string(h.Sum(nil)))
os.Exit(0)
return nil
}

func printFlags() {
type jsonFlag struct {
 Name string `json:"Name"`
 Bool bool `json:"Bool"`
 Usage string `json:"Usage"`
}
var flags []jsonFlag = nil
flag.VisitAll(func(f *flag.Flag) {
 switch f.Name {
 case "debug", "cpuprofile", "memprofile", "trace", "fix":
  return
 }
 b, ok := f.Value.(interface{ IsBoolFlag() bool })
 isBool := ok && b.IsBoolFlag()
 flags = append(flags, jsonFlag{f.Name, isBool, f.Usage})
})
