func (c *Config) compile() {
c.compiledSigRegexps = nil
c.compiledInterfaceRegexps = nil
for _, r := range c.IgnoreSigRegexps {
 if re, err := regexp.Compile(r); err == nil {
  c.compiledSigRegexps = append(c.compiledSigRegexps, re)
 }
}
for _, r := range c.IgnoreInterfaceRegexps {
 if re, err := regexp.Compile(r); err == nil {
  c.compiledInterfaceRegexps = append(c.compiledInterfaceRegexps, re)
 }
}
}

func parseSimpleYAML(data string) (Config, bool) {
cfg := defaultConfig()
hasIgnoreSigs := false
lines := strings.Split(data, "\n")
var currentList *[]string
for _, raw := range lines {
 trimmed := strings.TrimSpace(raw)
 if trimmed == "" || strings.HasPrefix(trimmed, "#") {
  continue
 }
 if !strings.HasPrefix(trimmed, "-") && strings.Contains(trimmed, ":") {
  parts := strings.SplitN(trimmed, ":", 2)
  key := strings.TrimSpace(parts[0])
  val := strings.TrimSpace(parts[1])
  switch key {
  case "ignoreSigs":
   hasIgnoreSigs = true
   cfg.IgnoreSigs = []string{}
   currentList = &cfg.IgnoreSigs
   if val == "[]" {
    currentList = nil
   }
  case "extraIgnoreSigs":
   cfg.ExtraIgnoreSigs = []string{}
   currentList = &cfg.ExtraIgnoreSigs
  case "ignoreSigRegexps":
   cfg.IgnoreSigRegexps = []string{}
   currentList = &cfg.IgnoreSigRegexps
  case "ignorePackageGlobs":
   cfg.IgnorePackageGlobs = []string{}
   currentList = &cfg.IgnorePackageGlobs
  case "ignoreInterfaceRegexps":
   cfg.IgnoreInterfaceRegexps = []string{}
   currentList = &cfg.IgnoreInterfaceRegexps
  case "reportInternalErrors":
   lower := strings.ToLower(val)
   if lower == "true" {
    cfg.ReportInternalErrors = true
   } else if lower == "false" {
    cfg.ReportInternalErrors = false
   }
   currentList = nil
  default:
   currentList = nil
  }
  continue
 }
 if strings.HasPrefix(trimmed, "-") {
  if currentList == nil {
   continue
  }
  item := strings.TrimSpace(strings.TrimPrefix(trimmed, "-"))
  item = strings.Trim(item, "\"'`")
  item = strings.TrimSpace(item)
  if item == "" {
   continue
  }
  *currentList = append(*currentList, item)
  continue
 }
}
return cfg, hasIgnoreSigs
}

