type Config struct {
IgnoreSigs             []string
ExtraIgnoreSigs        []string
IgnoreSigRegexps       []string
IgnorePackageGlobs     []string
IgnoreInterfaceRegexps []string
ReportInternalErrors   bool
compiledSigRegexps       []*regexp.Regexp
compiledInterfaceRegexps []*regexp.Regexp
}

func defaultConfig() Config {
c := Config{
 IgnoreSigs: []string{
  ".Errorf(",
  "errors.New(",
  "errors.Unwrap(",
  "errors.Join(",
  ".Wrap(",
  ".Wrapf(",
  ".WithMessage(",
  ".WithMessagef(",
  ".WithStack(",
 },
}
