}

func (c *Config) compile() {
c.compiledSigRegexps = nil
c.compiledInterfaceRegexps = nil
for _, r := range c.IgnoreSigRegexps {
 if re, err := regexp.Compile(r); err == nil {
  c.compiledSigRegexps = append(c.compiledSigRegexps, re)
 }
}
for _, r := range c.IgnoreInterfaceRegexps {
 if re, err := regexp.Compile(r); err == nil {
  c.compiledInterfaceRegexps = append(c.compiledInterfaceRegexps, re)
 }
}
}

func parseSimpleYAML(data string) (Config, bool) {
cfg := defaultConfig()
hasIgnoreSigs := false
lines := strings.Split(data, "\n")
var currentList *[]string
for _, raw := range lines {
 trimmed := strings.TrimSpace(raw)
 if trimmed == "" || strings.HasPrefix(trimmed, "#") {
  continue
 }
 if !strings.HasPrefix(trimmed, "-") && strings.Contains(trimmed, ":") {
  parts := strings.SplitN(trimmed, ":", 2)
  key := strings.TrimSpace(parts[0])
  val := strings.TrimSpace(parts[1])
  switch key {
  case "ignoreSigs":
   hasIgnoreSigs = true
   cfg.IgnoreSigs = []string{}
   currentList = &cfg.IgnoreSigs
   if val == "[]" {
    currentList = nil
   }
  case "extraIgnoreSigs":
   cfg.ExtraIgnoreSigs = []string{}
   currentList = &cfg.ExtraIgnoreSigs
  case "ignoreSigRegexps":
   cfg.IgnoreSigRegexps = []string{}
   currentList = &cfg.IgnoreSigRegexps
  case "ignorePackageGlobs":
   cfg.IgnorePackageGlobs = []string{}
   currentList = &cfg.IgnorePackageGlobs
  case "ignoreInterfaceRegexps":
   cfg.IgnoreInterfaceRegexps = []string{}
   currentList = &cfg.IgnoreInterfaceRegexps
  case "reportInternalErrors":
   lower := strings.ToLower(val)
   if lower == "true" {
    cfg.ReportInternalErrors = true
   } else if lower == "false" {
    cfg.ReportInternalErrors = false
   }
   currentList = nil
  default:
   currentList = nil
  }
  continue
 }
 if strings.HasPrefix(trimmed, "-") {
  if currentList == nil {
   continue
  }
  item := strings.TrimSpace(strings.TrimPrefix(trimmed, "-"))
  item = strings.Trim(item, "\"'`")
  item = strings.TrimSpace(item)
  if item == "" {
   continue
  }
  *currentList = append(*currentList, item)
  continue
 }
}
return cfg, hasIgnoreSigs
}

func loadConfig() Config {
def := defaultConfig()
wd, err := os.Getwd()
if err != nil {
 return def
}
path1 := filepath.Join(wd, ".wrapcheck.yaml")
data, err := os.ReadFile(path1)
if err != nil {
 return def
}
cfg, _ := parseSimpleYAML(string(data))
cfg.compile()
return cfg
}

func checkYAMLValid(data string) error {
if strings.Contains(data, "[") {
 open := strings.Count(data, "[")
 close := strings.Count(data, "]")
 if open != close {
  return fmt.Errorf("yaml: line 1: did not find expected ',' or ']'")
 }
}
return nil
}

type pkgJSON struct {
Dir string `json:"Dir"`
ImportPath string `json:"ImportPath"`
GoFiles []string `json:"GoFiles"`
TestGoFiles []string `json:"TestGoFiles"`
Imports []string `json:"Imports"`
}

func goList(dir, pattern string) ([]*pkgJSON, error) {
cmd := exec.Command("go", "list", "-json", pattern)
cmd.Dir = dir
out, err := cmd.CombinedOutput()
if err != nil && len(out) == 0 {
 return nil, fmt.Errorf("%s", string(out))
}
dec := json.NewDecoder(strings.NewReader(string(out)))
var pkgs []*pkgJSON
for {
 var p pkgJSON
 if err := dec.Decode(&p); err != nil {
  if err == io.EOF {
   break
  }
  break
 }
 pkgs = append(pkgs, &p)
}
return pkgs, nil
}

type loader struct {
fset *token.FileSet
pkgs map[string]*types.Package
infos map[string]*types.Info
files map[string][]*ast.File
goroot string
}

func newLoader() *loader {
goroot := os.Getenv("GOROOT")
if goroot == "" {
 goroot = "/usr/local/go"
}
return &loader{
 fset: token.NewFileSet(),
 pkgs: make(map[string]*types.Package),
 infos: make(map[string]*types.Info),
 files: make(map[string][]*ast.File),
 goroot: goroot,
}
}

func (l *loader) loadRecursive(dir, importPath string, visited map[string]bool) (*types.Package, *types.Info, []*ast.File, error) {
if visited[importPath] {
 if pkg, ok := l.pkgs[importPath]; ok {
  return pkg, l.infos[importPath], l.files[importPath], nil
 }
}
visited[importPath] = true
pkgs, err := goList(dir, importPath)
if err != nil || len(pkgs) == 0 {
 imp := importer.Default()
 if imp != nil {
  p, err2 := imp.Import(importPath)
  if err2 == nil {
   l.pkgs[importPath] = p
   return p, nil, nil, nil
  }
 }
 return nil, nil, nil, fmt.Errorf("cannot list %s", importPath)
}
pj := pkgs[0]
isStd := strings.HasPrefix(pj.Dir, l.goroot)
if isStd {
 imp := importer.Default()
 p, err := imp.Import(importPath)
 if err == nil {
  l.pkgs[importPath] = p
  return p, nil, nil, nil
 }
}
for _, dep := range pj.Imports {
 if _, ok := l.pkgs[dep]; !ok {
  l.loadRecursive(dir, dep, visited)
 }
}
var files []*ast.File
for _, gf := range pj.GoFiles {
 fp := filepath.Join(pj.Dir, gf)
 f, err := parser.ParseFile(l.fset, fp, nil, parser.ParseComments)
 if err != nil {
  return nil, nil, nil, err
 }
 files = append(files, f)
}
conf := types.Config{
 Importer: &mapImporter{pkgs: l.pkgs},
}
info := &types.Info{
 Types: make(map[ast.Expr]types.TypeAndValue),
 Defs: make(map[*ast.Ident]types.Object),
 Uses: make(map[*ast.Ident]types.Object),
}
pkg, err := conf.Check(pj.ImportPath, l.fset, files, info)
if err != nil {
 // ignore
}
l.pkgs[pj.ImportPath] = pkg
l.infos[pj.ImportPath] = info
l.files[pj.ImportPath] = files
return pkg, info, files, nil
}

func (l *loader) loadPattern(dir, pattern string, includeTests bool) ([]*pkgJSON, map[string][]*ast.File, map[string]*types.Info, map[string]*types.Package, error) {
pkgs, err := goList(dir, pattern)
if err != nil {
 return nil, nil, nil, nil, err
}
resultFiles := make(map[string][]*ast.File)
resultInfos := make(map[string]*types.Info)
resultPkgs := make(map[string]*types.Package)
visited := make(map[string]bool)
for _, pj := range pkgs {
 if len(pj.Dir) == 0 {
  continue
 }
 isStd := strings.HasPrefix(pj.Dir, l.goroot)
 if isStd {
  imp := importer.Default()
  p, err := imp.Import(pj.ImportPath)
  if err == nil {
   resultPkgs[pj.ImportPath] = p
   continue
  }
 }
 for _, dep := range pj.Imports {
  if _, ok := l.pkgs[dep]; !ok {
   l.loadRecursive(dir, dep, visited)
  }
 }
 allGoFiles := pj.GoFiles
 if includeTests {
  allGoFiles = append(allGoFiles, pj.TestGoFiles...)
 }
 var files []*ast.File
 for _, gf := range allGoFiles {
  fp := filepath.Join(pj.Dir, gf)
  f, err := parser.ParseFile(l.fset, fp, nil, parser.ParseComments)
  if err != nil {
   continue
  }
  files = append(files, f)
 }
 conf := types.Config{
  Importer: &mapImporter{pkgs: l.pkgs},
 }
 info := &types.Info{
  Types: make(map[ast.Expr]types.TypeAndValue),
  Defs: make(map[*ast.Ident]types.Object),
  Uses: make(map[*ast.Ident]types.Object),
 }
 pkg, _ := conf.Check(pj.ImportPath, l.fset, files, info)
 l.pkgs[pj.ImportPath] = pkg
 l.infos[pj.ImportPath] = info
 l.files[pj.ImportPath] = files
 resultFiles[pj.ImportPath] = files
 resultInfos[pj.ImportPath] = info
 resultPkgs[pj.ImportPath] = pkg
}
return pkgs, resultFiles, resultInfos, resultPkgs, nil
}

type mapImporter struct {
pkgs map[string]*types.Package
}

func (m *mapImporter) Import(path string) (*types.Package, error) {
if p, ok := m.pkgs[path]; ok {
 return p, nil
}
imp := importer.Default()
if imp != nil {
 return imp.Import(path)
}
return nil, fmt.Errorf("package %s not found", path)
}

type originInfo struct {
sig string
pkgPath string
isInterface bool
interfaceName string
isIgnored bool
}

func isErrorOrContainsError(t types.Type) bool {
if t == nil {
 return false
}
s := t.String()
if s == "error" {
 return true
}
if tup, ok := t.(*types.Tuple); ok {
 for i := 0; i < tup.Len(); i++ {
  if tup.At(i).Type().String() == "error" {
   return true
  }
 }
}
if strings.Contains(s, "error") {
 return true
}
return false
}

func getCallOrigin(call *ast.CallExpr, info *types.Info, cfg *Config) *originInfo {
var obj types.Object
switch fun := call.Fun.(type) {
case *ast.Ident:
 obj = info.ObjectOf(fun)
case *ast.SelectorExpr:
 obj = info.ObjectOf(fun.Sel)
}
if obj == nil {
 return nil
}
sigStr := obj.String()
pkgPath := ""
if obj.Pkg() != nil {
 pkgPath = obj.Pkg().Path()
}
isIgnored := false
for _, ign := range cfg.IgnoreSigs {
 if strings.Contains(sigStr, ign) {
  isIgnored = true
  break
 }
}
if !isIgnored {
 for _, ign := range cfg.ExtraIgnoreSigs {
  if strings.Contains(sigStr, ign) {
   isIgnored = true
   break
  }
 }
}
if !isIgnored {
 for _, re := range cfg.compiledSigRegexps {
  if re.MatchString(sigStr) {
   isIgnored = true
   break
  }
 }
}
isInterface := false
interfaceName := ""
if sel, ok := call.Fun.(*ast.SelectorExpr); ok {
 if tv, ok := info.Types[sel.X]; ok {
  t := tv.Type
  if ptr, ok := t.(*types.Pointer); ok {
   t = ptr.Elem()
  }
  if _, ok := t.Underlying().(*types.Interface); ok {
   isInterface = true
   if named, ok := tv.Type.(*types.Named); ok {
    interfaceName = named.Obj().Name()
   } else {
    interfaceName = t.String()
   }
  } else if named, ok := t.(*types.Named); ok {
   if _, ok := named.Underlying().(*types.Interface); ok {
    isInterface = true
    interfaceName = named.Obj().Name()
   }
  }
 }
}
return &originInfo{
 sig: sigStr,
 pkgPath: pkgPath,
 isInterface: isInterface,
 interfaceName: interfaceName,
 isIgnored: isIgnored,
}
}

type Diagnostic struct {
Posn string `json:"posn"`
Message string `json:"message"`
}

func shouldIgnorePkg(pkgPath string, cfg *Config) bool {
for _, glob := range cfg.IgnorePackageGlobs {
 matched, _ := path.Match(glob, pkgPath)
 if matched {
  return true
 }
 matched, _ = filepath.Match(glob, pkgPath)
 if matched {
  return true
 }
}
return false
}

func shouldIgnoreInterface(interfaceName string, cfg *Config) bool {
for _, re := range cfg.compiledInterfaceRegexps {
 if re.MatchString(interfaceName) {
  return true
 }
}
return false
}

func analyzePackage(files []*ast.File, info *types.Info, fset *token.FileSet, cfg *Config, curPkgPath string) []Diagnostic {
var diags []Diagnostic
for _, f := range files {
 for _, decl := range f.Decls {
  fn, ok := decl.(*ast.FuncDecl)
  if !ok {
   continue
  }
  if fn.Body == nil {
   continue
  }
  env := make(map[types.Object]*originInfo)
  var processStmts func(stmts []ast.Stmt)
  var processStmt func(stmt ast.Stmt)
  processStmt = func(stmt ast.Stmt) {
   switch s := stmt.(type) {
   case *ast.AssignStmt:
    for i, lhs := range s.Lhs {
     ident, ok := lhs.(*ast.Ident)
     if !ok {
      continue
     }
     obj := info.ObjectOf(ident)
     if obj == nil {
      continue
     }
     var origin *originInfo
     if len(s.Rhs) == 1 {
      rhs := s.Rhs[0]
      switch r := rhs.(type) {
      case *ast.CallExpr:
       origin = getCallOrigin(r, info, cfg)
      case *ast.Ident:
       if srcObj := info.ObjectOf(r); srcObj != nil {
        if srcOrigin, ok := env[srcObj]; ok {
         origin = srcOrigin
        }
       }
      }
     } else {
      if i < len(s.Rhs) {
       rhs := s.Rhs[i]
       switch r := rhs.(type) {
       case *ast.CallExpr:
        origin = getCallOrigin(r, info, cfg)
       case *ast.Ident:
        if srcObj := info.ObjectOf(r); srcObj != nil {
         if srcOrigin, ok := env[srcObj]; ok {
          origin = srcOrigin
         }
        }
       }
      }
     }
     if origin != nil {
      env[obj] = origin
     }
    }
   case *ast.DeclStmt:
    if gen, ok := s.Decl.(*ast.GenDecl); ok {
     for _, spec := range gen.Specs {
      if vs, ok := spec.(*ast.ValueSpec); ok {
       for i, name := range vs.Names {
        obj := info.ObjectOf(name)
        if obj == nil {
         continue
        }
        var origin *originInfo
        if i < len(vs.Values) {
         rhs := vs.Values[i]
         switch r := rhs.(type) {
         case *ast.CallExpr:
          origin = getCallOrigin(r, info, cfg)
         case *ast.Ident:
          if srcObj := info.ObjectOf(r); srcObj != nil {
           if srcOrigin, ok := env[srcObj]; ok {
            origin = srcOrigin
           }
          }
         }
        } else if len(vs.Values) == 1 {
         rhs := vs.Values[0]
         switch r := rhs.(type) {
         case *ast.CallExpr:
          origin = getCallOrigin(r, info, cfg)
         case *ast.Ident:
          if srcObj := info.ObjectOf(r); srcObj != nil {
           if srcOrigin, ok := env[srcObj]; ok {
            origin = srcOrigin
           }
          }
         }
        }
        if origin != nil {
         env[obj] = origin
        }
       }
      }
     }
    }
   case *ast.ReturnStmt:
    for _, expr := range s.Results {
     tv, ok := info.Types[expr]
     if !ok {
      continue
     }
     if !isErrorOrContainsError(tv.Type) {
      continue
     }
     var origin *originInfo
     var pos token.Pos
     pos = expr.Pos()
     switch e := expr.(type) {
     case *ast.Ident:
      if obj := info.ObjectOf(e); obj != nil {
       if o, ok := env[obj]; ok {
        origin = o
       }
      }
      pos = e.Pos()
     case *ast.CallExpr:
      origin = getCallOrigin(e, info, cfg)
      pos = e.Pos()
     default:
      pos = expr.Pos()
     }
     if origin == nil {
      continue
     }
     if origin.isIgnored {
      continue
     }
     if shouldIgnorePkg(origin.pkgPath, cfg) {
      continue
     }
     if origin.isInterface && shouldIgnoreInterface(origin.interfaceName, cfg) {
      continue
     }
     var msg string
     if origin.isInterface {
      msg = fmt.Sprintf("error returned from interface method should be wrapped: sig: %s", origin.sig)
     } else if origin.pkgPath != curPkgPath {
      msg = fmt.Sprintf("error returned from external package is unwrapped: sig: %s", origin.sig)
     } else {
      if !cfg.ReportInternalErrors {
       continue
      }
      msg = fmt.Sprintf("package-internal error should be wrapped: sig: %s", origin.sig)
     }
     position := fset.Position(pos)
     posnStr := fmt.Sprintf("%s:%d:%d", position.Filename, position.Line, position.Column)
     diags = append(diags, Diagnostic{Posn: posnStr, Message: msg})
    }
   case *ast.IfStmt:
    if s.Body != nil {
     processStmts(s.Body.List)
    }
    if s.Else != nil {
     switch elseStmt := s.Else.(type) {
     case *ast.BlockStmt:
      processStmts(elseStmt.List)
     case *ast.IfStmt:
      processStmt(elseStmt)
     }
    }
    if s.Init != nil {
     processStmt(s.Init)
    }
   case *ast.BlockStmt:
    processStmts(s.List)
   case *ast.ForStmt:
    if s.Body != nil {
     processStmts(s.Body.List)
    }
   case *ast.RangeStmt:
    if s.Body != nil {
     processStmts(s.Body.List)
    }
   case *ast.SwitchStmt:
    if s.Body != nil {
     for _, cc := range s.Body.List {
      if caseClause, ok := cc.(*ast.CaseClause); ok {
       processStmts(caseClause.List)
      }
     }
    }
   case *ast.TypeSwitchStmt:
    if s.Body != nil {
     for _, cc := range s.Body.List {
      if caseClause, ok := cc.(*ast.CaseClause); ok {
       processStmts(caseClause.List)
      }
     }
    }
   case *ast.SelectStmt:
    if s.Body != nil {
     for _, cc := range s.Body.List {
      if commClause, ok := cc.(*ast.CommClause); ok {
       processStmts(commClause.Body)
      }
     }
    }
   case *ast.LabeledStmt:
    processStmt(s.Stmt)
   }
  }
  processStmts = func(stmts []ast.Stmt) {
   for _, st := range stmts {
    processStmt(st)
   }
  }
  processStmts(fn.Body.List)
 }
}
return diags
}

type versionFlag struct{}

func (versionFlag) IsBoolFlag() bool { return true }
func (versionFlag) String() string { return "" }
func (versionFlag) Set(s string) error {
if s != "full" {
 log.Fatalf("unsupported flag value: -V=%s (use -V=full)", s)
}
prog, err := os.Executable()
if err != nil {
 log.Fatal(err)
}
f, err := os.Open(prog)
if err != nil {
 log.Fatal(err)
}
defer f.Close()
h := sha256.New()
if _, err := io.Copy(h, f); err != nil {
 log.Fatal(err)
}
fmt.Printf("%s version devel comments-go-here buildID=%02x\n", prog, string(h.Sum(nil)))
os.Exit(0)
return nil
}

func printFlags() {
type jsonFlag struct {
 Name string `json:"Name"`
 Bool bool `json:"Bool"`
 Usage string `json:"Usage"`
}
var flags []jsonFlag = nil
flag.VisitAll(func(f *flag.Flag) {
 switch f.Name {
 case "debug", "cpuprofile", "memprofile", "trace", "fix":
  return
 }
 b, ok := f.Value.(interface{ IsBoolFlag() bool })
 isBool := ok && b.IsBoolFlag()
 flags = append(flags, jsonFlag{f.Name, isBool, f.Usage})
})
data, _ := json.MarshalIndent(flags, "", "\t")
os.Stdout.Write(data)
}

