 jsonOutput bool
 contextLines int
 fixFlag bool
 diffFlag bool
 includeTests bool
 allFlag bool
 sourceFlag bool
 tagsFlag string
 vFlag bool
 cpuprofile string
 memprofile string
 trace string
 debug string
 printFlagsFlag bool
)

flag.BoolVar(&printFlagsFlag, "flags", false, "print analyzer flags in JSON")
flag.Var(versionFlag{}, "V", "print version and exit")
flag.BoolVar(&jsonOutput, "json", false, "emit JSON output")
flag.IntVar(&contextLines, "c", -1, "display offending line with this many lines of context")
flag.BoolVar(&fixFlag, "fix", false, "apply all suggested fixes")
flag.BoolVar(&diffFlag, "diff", false, "with -fix, don't update the files, but print a unified diff")
flag.BoolVar(&includeTests, "test", true, "indicates whether test files should be analyzed, too")
flag.BoolVar(&allFlag, "all", false, "no effect (deprecated)")
flag.BoolVar(&sourceFlag, "source", false, "no effect (deprecated)")
flag.StringVar(&tagsFlag, "tags", "", "no effect (deprecated)")
flag.BoolVar(&vFlag, "v", false, "no effect (deprecated)")
flag.StringVar(&cpuprofile, "cpuprofile", "", "write CPU profile to this file")
flag.StringVar(&memprofile, "memprofile", "", "write memory profile to this file")
flag.StringVar(&trace, "trace", "", "write trace log to this file")
flag.StringVar(&debug, "debug", "", "debug flags, any subset of \"fpstv\"")

flag.Usage = func() {
 fmt.Fprintf(os.Stderr, "wrapcheck: Checks that errors returned from external packages are wrapped\n\n")
 fmt.Fprintf(os.Stderr, "Usage: %s [-flag] [package]\n\n\n", "wrapcheck")
 fmt.Fprintf(os.Stderr, "Flags:\n")
 flag.PrintDefaults()
}

flag.Parse()

if printFlagsFlag {
 printFlags()
 os.Exit(0)
}

args := flag.Args()
if len(args) == 0 {
 flag.Usage()
 os.Exit(1)
}

wd, _ := os.Getwd()
cfgPath := filepath.Join(wd, ".wrapcheck.yaml")
if data, err := os.ReadFile(cfgPath); err == nil {
 if err := checkYAMLValid(string(data)); err != nil {
  log.Fatalf("failed to parse config: While parsing config: %v", err)
 }
}

cfg := loadConfig()

l := newLoader()

hasDiags := false
hasErrors := false
jsonResults := make(map[string]map[string]interface{})

for _, pattern := range args {
 pkgs, filesMap, infosMap, _, err := l.loadPattern(wd, pattern, includeTests)
 if err != nil {
  continue
 }
 for _, pj := range pkgs {
  importPath := pj.ImportPath
  if pj.Incomplete || len(pj.DepsErrors) > 0 || pj.Error != nil {
   hasErrors = true
   if jsonOutput {
    if _, ok := jsonResults[importPath]; !ok {
     jsonResults[importPath] = make(map[string]interface{})
    }
    jsonResults[importPath]["wrapcheck"] = map[string]string{"error": "analysis skipped due to errors in package"}
   } else {
    for _, de := range pj.DepsErrors {
     fmt.Fprintf(os.Stderr, "%s: %s\n", de.Pos, de.Err)
    }
    if len(pj.DepsErrors) > 0 {
     de := pj.DepsErrors[0]
     failingImport := ""
     if len(de.ImportStack) > 0 {
      failingImport = de.ImportStack[0]
     }
     if failingImport != "" {
      fmt.Fprintf(os.Stderr, "%s: could not import %s (invalid package name: \"\")\n", de.Pos, failingImport)
     }
    }
    fmt.Fprintf(os.Stderr, "wrapcheck: analysis skipped due to errors in package\n")
   }
   continue
  }
  files, ok := filesMap[importPath]
  if !ok {
   continue
  }
  info, ok := infosMap[importPath]
  if !ok {
   continue
  }
  diags := analyzePackage(files, info, l.fset, &cfg, importPath)
  if len(diags) > 0 {
   hasDiags = true
   if jsonOutput {
    if _, ok := jsonResults[importPath]; !ok {
     jsonResults[importPath] = make(map[string]interface{})
    }
    jsonResults[importPath]["wrapcheck"] = diags
   } else {
    for _, d := range diags {
     fmt.Fprintf(os.Stderr, "%s: %s\n", d.Posn, d.Message)
     if contextLines >= 0 {
      parts := strings.Split(d.Posn, ":")
      if len(parts) >= 3 {
       fname := parts[0]
       var lineNum int
       fmt.Sscanf(parts[1], "%d", &lineNum)
       content, err := os.ReadFile(fname)
       if err == nil {
        lines := strings.Split(string(content), "\n")
        start := lineNum - contextLines - 1
        if start < 0 {
         start = 0
        }
        end := lineNum + contextLines
        if end > len(lines) {
         end = len(lines)
        }
        for i := start; i < end; i++ {
         fmt.Fprintf(os.Stderr, "%d\t%s\n", i+1, lines[i])
        }
       }
      }
     }
    }
   }
  }
 }
}

if jsonOutput {
 if len(jsonResults) == 0 {
  fmt.Println("{}")
 } else {
  data, _ := json.MarshalIndent(jsonResults, "", "\t")
  fmt.Println(string(data))
 }
 os.Exit(0)
}

if hasErrors {
 os.Exit(1)
}
if hasDiags {
 os.Exit(3)
}
os.Exit(0)
}
