package pkg1
import "example.com/ext"
func MyWrap(e error) error { return e }
func Foo() error {
    err := ext.Do()
    return MyWrap(err)
}
EOF
/workspace/executable ./... 2>&1; echo exit:$?
/workspace/executable -json ./... 2>&1

cat > pkg1/pkg1.go <<'EOF'
package pkg1
import "example.com/ext"
import "fmt"
func MyWrap(err error, msg string) error { return fmt.Errorf("%s: %w", msg, err) }
func Foo() error {
    err := ext.Do()
    return MyWrap(err, "msg")
}
EOF
/workspace/executable ./... 2>&1; echo exit:$? should report because MyWrap not in ignore list

cat <<'YAML' > .wrapcheck.yaml
extraIgnoreSigs:
- MyWrap
YAML
/workspace/executable ./... 2>&1; echo exit:$? should be clean
rm .wrapcheck.yaml

cat > pkg1/pkg1.go <<'EOF'
package pkg1
import "example.com/ext"
import "fmt"
func Wrap(err error, msg string) error { return fmt.Errorf("%s: %w", msg, err) }
func Foo() error {
    err := ext.Do()
    return Wrap(err, "msg")
}
EOF
/workspace/executable ./... 2>&1; echo exit:$? should be clean because Wrap matches .Wrap(

# Reset
cat > pkg1/pkg1.go <<'EOF'
package pkg1
import "example.com/ext"
func Foo() error {
    err := ext.Do()
    return err
}
EOF
/workspace/executable ./... 2>&1
